import{_ as e,o as a,c as o,ah as n}from"./chunks/framework.D4KxWb5R.js";const f=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"src/en/guide/introduction.md"}'),i={name:"en/guide/introduction.md"};function r(s,t,d,c,h,u){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>M&#39;City IQ is the internal platform of M&#39;City IQ Ltd. It brings together three spaces, reached with a single account:</p><ul><li><strong>the public site</strong> (<a href="https://mcityiq.com" target="_blank" rel="noreferrer">mcityiq.com</a>): M&#39;City, its products and its zones, and a contact form;</li><li><strong>the intranet</strong>: your desk, communications, shared resources and a space for each product;</li><li><strong>the M&#39;City back-office</strong>: the product and zone registry, accounts, site content, supervision and configuration, depending on your position.</li></ul><p>The <strong>products</strong> M&#39;City runs, such as Auticway, each have their own back-office. M&#39;City IQ never handles their operations: it opens them for you through single sign-on (SSO) when you are granted access.</p><h2 id="who-reads-what" tabindex="-1">Who reads what <a class="header-anchor" href="#who-reads-what" aria-label="Permalink to &quot;Who reads what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You are…</th><th>Read</th></tr></thead><tbody><tr><td>A member of the M&#39;City team</td><td><a href="./getting-started.html">Getting started</a>, <a href="./desk.html">The desk</a>, <a href="./notifications.html">Notifications</a>, <a href="./account.html">My account</a></td></tr><tr><td>Interested in a specific position</td><td><a href="./positions.html">By position</a></td></tr><tr><td>An administrator (CEO, Product Operations, Support, HR)</td><td>The <a href="./administration/accounts.html">Administration</a> part</td></tr><tr><td>A user of the Auticway back-office</td><td><a href="./auticway.html">Auticway back-office</a></td></tr><tr><td>A product&#39;s technical team</td><td>The <a href="./integration/overview.html">Technical integration</a> part</td></tr></tbody></table><h2 id="key-notions" tabindex="-1">Key notions <a class="header-anchor" href="#key-notions" aria-label="Permalink to &quot;Key notions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Notion</th><th>Definition</th></tr></thead><tbody><tr><td>Position</td><td>Your job profile, one of seven. It decides which <strong>functions</strong> you see. An account has one active position.</td></tr><tr><td>Scope</td><td>The products, zones and offices assigned to your account. It decides which <strong>data</strong> you see in those functions.</td></tr><tr><td>Team</td><td>A group of named accounts responsible for one or more products. An account can belong to several teams.</td></tr><tr><td>Zone</td><td>A specific urban or peri-urban area. Only a <strong>qualified</strong> zone can be attached to a product.</td></tr><tr><td>Office</td><td>A physical M&#39;City location, tied to a zone.</td></tr><tr><td>Department</td><td>A unit of the organization, used to target communications.</td></tr><tr><td>Product back-office</td><td>A product&#39;s own administration tool (e.g. the Auticway back-office).</td></tr><tr><td>SSO</td><td>Single sign-on: your M&#39;City account opens the intranet, the M&#39;City back-office and the product back-offices you are granted.</td></tr><tr><td>General administrator</td><td>The CEO, or a delegated account: invites accounts and manages the configuration.</td></tr></tbody></table><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p>The interface is available in English and French. You choose your working language in <a href="./account.html#language">My account</a>; it applies to the whole intranet and to your notifications. Published content (communications, resources, site pages) is entered in English and French; when the French is missing, the English text is shown.</p>',10)])])}const g=e(i,[["render",r]]);export{f as __pageData,g as default};
